CREATE COLUMN TABLE "TEST_AP"."ANCM" ("AbsEntry" INTEGER CS_INT NOT NULL , "NcmCode" NVARCHAR(15) NOT NULL , "Descrip" NVARCHAR(254), "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "GroupCode" NVARCHAR(1) DEFAULT '0' NOT NULL , "Group" SMALLINT CS_INT, PRIMARY KEY ("AbsEntry", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ANCM_CODE" ON "TEST_AP"."ANCM" ( "NcmCode" ASC, "GroupCode" ASC, "LogInstanc" ASC )